		w.Header().Set("Content-Type", "application/json")
		if replayed {
			w.Header().Set("Idempotency-Replayed", "true")
		} else {
			w.Header().Set("Idempotency-Replayed", "false")
		}
		w.WriteHeader(200)
		_ = json.NewEncoder(w).Encode(result)
	})
}

func reject(w http.ResponseWriter, status int) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]string{"error": http.StatusText(status)})
}

func decode(body []byte) ([]string, bool) {
	if !utf8.Valid(body) {
		return nil, false
	}
	d := json.NewDecoder(bytes.NewReader(body))
	if token, err := d.Token(); err != nil || token != json.Delim('{') {
		return nil, false
	}
	if key, err := d.Token(); err != nil || key != "ids" {
		return nil, false
	}
	var raw []json.RawMessage
	if d.Decode(&raw) != nil {
		return nil, false
	}
	if token, err := d.Token(); err != nil || token != json.Delim('}') {
		return nil, false
	}
	if d.Decode(new(any)) != io.EOF {
		return nil, false
	}
	ids := make([]string, len(raw))
	for i, value := range raw {
		if len(value) == 0 || value[0] != '"' || json.Unmarshal(value, &ids[i]) != nil {
			return nil, false
		}
	}
	ids, err := canonical(ids)
	return ids, err == nil
}

// Identical adapter and validation in both experiment conditions.
type Result struct {
	ApprovedIDs []string `json:"approvedIds"`
}
type Rejection struct{ Status int }

func (r *Rejection) Error() string { return fmt.Sprintf("action rejected: %d", r.Status) }

type Approve func(context.Context, app.Identity, string, []string) (Result, bool, error)

func canonical(ids []string) ([]string, error) {
	if len(ids) < 1 || len(ids) > 100 {
		return nil, &Rejection{400}
	}
	result := append([]string(nil), ids...)
	sort.Strings(result)
	for i, id := range result {
		if len(id) == 0 || len(id) > 100 || !utf8.ValidString(id) || (i > 0 && result[i-1] == id) {
			return nil, &Rejection{400}
		}
	}
	return result, nil
}

func validKey(key string) bool {
	if len(key) < 1 || len(key) > 128 {
		return false
	}
	for _, c := range key {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("._:-", c)) {
			return false
		}
	}
	return true
}

// Batch approval with audit logs and scoped idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"sort"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const bulkApproveOperation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// Validate: no null bytes in IDs
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}

		// Calculate requestHash: "bulk-approve.v3\n" + sorted "<len>:<id>" concatenated
		hashInput := bulkApproveOperation + "\n"
		for _, id := range ids {
			hashInput += fmt.Sprintf("%d:%s", len(id), id)
		}
		hash := sha256.Sum256([]byte(hashInput))
		requestHash := hex.EncodeToString(hash[:])

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		// Set context for RLS
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Lock eligible purchases for update
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		eligible := make([]string, 0, len(ids))
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// If any target is invalid, reject all
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Sort ids to ensure consistent hashing (already sorted in canonical, but ensure)
		sortedIDs := make([]string, len(ids))
		copy(sortedIDs, ids)
		sort.Strings(sortedIDs)

		// Check for existing idempotency key in the same scope
		// Scope: operation + tenantId + actorId + key
		var existingAction struct {
			Exists       bool
			RequestHash  string
			ResponseJSON string
		}

		err = tx.QueryRow(ctx, `
			SELECT true, "requestHash", response::text
			FROM "ActionRequest"
			WHERE "tenantId" = $1 AND "actorId" = $2 AND operation = $3 AND key = $4
		`, u.Tenant, u.User, bulkApproveOperation, key).Scan(
			&existingAction.Exists,
			&existingAction.RequestHash,
			&existingAction.ResponseJSON,
		)

		if err != pgx.ErrNoRows {
			// Idempotency key exists
			if err != nil {
				return protocol.Result{}, false, err
			}

			// Check if it's the same request (same hash)
			if existingAction.RequestHash != requestHash {
				// Same key, different target set
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}

			// Same key and same target set - replayed request, return cached response
			var decoded protocol.Result
			if err := json.Unmarshal([]byte(existingAction.ResponseJSON), &decoded); err != nil {
				return protocol.Result{}, false, err
			}
			return decoded, true, nil
		}

		// No existing action - proceed with approval

		// Update purchases to approved
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Create response JSON with sorted IDs
		responseJSON := fmt.Sprintf(`{"approvedIds":[%s]}`, formatIDsForJSON(sortedIDs))

		// Insert ActionRequest for idempotency
		_, err = tx.Exec(ctx, `
			INSERT INTO "ActionRequest" ("tenantId", "actorId", operation, key, "requestHash", response)
			VALUES ($1, $2, $3, $4, $5, $6::jsonb)
		`, u.Tenant, u.User, bulkApproveOperation, key, requestHash, responseJSON)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Insert ApprovalAudit for each approved purchase
		for _, id := range ids {
			_, err = tx.Exec(ctx, `
				INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
				VALUES ($1, $2, $3, $4, $5, 'submitted', 'approved')
			`, u.Tenant, id, u.User, bulkApproveOperation, key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return protocol.Result{ApprovedIDs: sortedIDs}, false, nil
	}

	return protocol.HTTP(approve, fallback), nil
}

// formatIDsForJSON formats IDs for JSON array output
func formatIDsForJSON(ids []string) string {
	if len(ids) == 0 {
		return ""
	}
	parts := make([]string, len(ids))
	for i, id := range ids {
		parts[i] = fmt.Sprintf(`"%s"`, id)
	}
	return strings.Join(parts, ",")
}

