		}

		// Create response JSON with sorted IDs
		responseJSON := fmt.Sprintf(`{"approvedIds":[%s]}`, formatIDsForJSON(sortedIDs))

		// Insert ActionRequest for idempotency
		_, err = tx.Exec(ctx, `
			INSERT INTO "ActionRequest" ("tenantId", "actorId", operation, key, "requestHash", response)
			VALUES ($1, $2, $3, $4, $5, $6::jsonb)
		`, u.Tenant, u.User, bulkApproveOperation, key, requestHash, responseJSON)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Insert ApprovalAudit for each approved purchase
		for _, id := range ids {
			_, err = tx.Exec(ctx, `
				INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
				VALUES ($1, $2, $3, $4, $5, 'submitted', 'approved')
			`, u.Tenant, id, u.User, bulkApproveOperation, key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return protocol.Result{ApprovedIDs: sortedIDs}, false, nil
	}

	return protocol.HTTP(approve, fallback), nil
}

// formatIDsForJSON formats IDs for JSON array output
func formatIDsForJSON(ids []string) string {
	if len(ids) == 0 {
		return ""
	}
	parts := make([]string, len(ids))
	for i, id := range ids {
		parts[i] = fmt.Sprintf(`"%s"`, id)
	}
	return strings.Join(parts, ",")
}
